// TH16 v1.00a stage 3 wave: st03.ecl.txt MainSub07:1337-1371
// (deps Phantom01 1393-1412, Phantom01B 1414-1423, Phantom01R 1425-1434,
//  Phantom01_at 1436-1456). 3 rounds x 2 groups x 10 R/B pairs.
// Source frame t (MainSub07 entry) <-> card frame t + 124 (see report.md).

const TIME_LIMIT: int = 1330;
const OPENING_BUFFER: int = 120;

// Source etSprite(0, 7, 6): TH16 type 7, color 6.
const TH16_RING_BALL2: int = 464;
const BULLET_COLOR: int = 6;

// Source enmCreate(name, x, -32.0f, 100, 1000, 1); drops/scoring omitted.
const PHANTOM_HP: int = 100;
const PHANTOM_SCORE: int = 1000;

// Phantom01_at: etAngle(0, 0.0f, 0.5235988f) -> fan half-step 30 deg.
const FAN_STEP: angle = 30deg;
// Phantom01 / moveEllipseRel phase speed: 0.034906585 rad = 2 deg.
const SWAY_STEP: angle = 2deg;
const SWAY_RADIUS: fx = 10.0fx;

// MainSub07_204 / MainSub07_720: B = RANDF2 * 64 + A  (RANDF2 in [-1,1)).
sub spawn_pair_member(x0: fx, x1: fx, step: int, kind: int) {
    // floatTime(0, A, 100, 0, x0, x1): linear, one update per elapsed frame.
    var base: fx = x0 + (x1 - x0) * (step as fx) / 100fx;
    // RANDF2 in [-1,1) scaled by 64 -> signed offset in [-64,64).
    var off: fx = ((rand(65536) - 32768) as fx) / 512fx;
    var x: fx = base + off;
    _ = spawn_enemy(x, -32fx, PHANTOM_HP, 0, PHANTOM_SCORE, 0, phantom(kind));
}

// One 10-pair group spread over exactly 100 frames (5 frames between spawns).
// kind 1 = Phantom01R, 0 = Phantom01B (first member of the group).
sub spawn_group(x0: fx, x1: fx, first_kind: int) {
    for j in 0..10 {
        spawn_pair_member(x0, x1, 10 * j, first_kind);
        wait(5);
        spawn_pair_member(x0, x1, 10 * j + 5, 1 - first_kind);
        wait(5);
    }
}

// MainSub07_1152: C = 3 rounds; each round = R-first group, B-first group, wait(10).
sub wave() {
    for round in 0..3 {
        spawn_group(128.0fx, -128.0fx, 1);
        spawn_group(-128.0fx, 128.0fx, 0);
        wait(10);
    }
}

async sub phantom(kind: int) {
    // Phantom01: setHurtbox(28,28) / setHitbox(16,16) circle branch = r*0.5.
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var rank: int = global(GVAR_RANK);
    // Phantom01B sets I0=1; Phantom01R diffI(I0,0,1,1,1) -> no fire on Easy only.
    var fire_ok: int = 1;
    if kind == 1 && rank == RANK_EASY {
        fire_ok = 0;
    }
    // Phantom01 moveEllipseRel(F0, 2deg/f, 10, 0, ABS_ANGLE, ratio 0), s=0 and
    // axis = pi/2 gives a pure horizontal sway 10*cos(phase); the setter snaps to
    // phase 0 (x+10) on its configuration frame.
    move_to(0, $self_x + SWAY_RADIUS, $self_y, EASE_LINEAR);
    if fire_ok == 1 {
        spawn phantom_fire();
    }
    // ABS layer: moveVel(pi/2, 0.5) then moveVelTime(120, mode3, pi/2, 1.0):
    // quartic-in speed 0.5 -> 1.0 over 120 ticks, then constant.
    var phase: angle = 0deg;
    var k: int = 0;
    loop {
        var dx: fx = SWAY_RADIUS * cos(phase + SWAY_STEP) - SWAY_RADIUS * cos(phase);
        phase = phase + SWAY_STEP;
        var v: fx = 1fx;
        if k < 120 {
            var u: fx = ((k + 1) as fx) / 120fx;
            v = 0.5fx + 0.5fx * u * u * u * u;
        }
        move_vel_xy(0, dx, v, EASE_LINEAR);
        wait(1);
        k = k + 1;
    }
}

// Phantom01_at: configured on the next frame, then etOn after 20 + RAND%40.
async sub phantom_fire() {
    wait(20 + rand(40));
    var aim: angle = aim_player();
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        // etCountD/etSpeedD Easy: 1 route x 1 layer, speed 1.5.
        shoot_one(1.5fx, aim);
    } else if rank == RANK_NORMAL {
        // Normal: 1 route x 1 layer, speed 2.0.
        shoot_one(2.0fx, aim);
    } else if rank == RANK_HARD {
        // Hard: 1 route x 3 layers, speeds 3.0 / 2.0 / 1.0.
        shoot_layers(3.0fx, 1.0fx, aim);
    } else {
        // Lunatic: 3 routes (aim, aim-30, aim+30) x 3 layers, 4.0 / 2.5 / 1.0.
        var q: int = 0;
        while q < 3 {
            var v: fx = 4.0fx + (1.0fx - 4.0fx) * (q as fx) / 2fx;
            shoot_one(v, aim);
            shoot_one(v, aim - FAN_STEP);
            shoot_one(v, aim + FAN_STEP);
            q = q + 1;
        }
    }
}

sub shoot_layers(s0: fx, s1: fx, aim: angle) {
    var q: int = 0;
    while q < 3 {
        var v: fx = s0 + (s1 - s0) * (q as fx) / 2fx;
        shoot_one(v, aim);
        q = q + 1;
    }
}

// Birth ANIM (ex type 0x2, a=1) keeps position -= 4 * velocity; the anim itself
// is omitted. WAIT(0) after it is a same-tick no-op.
sub shoot_one(v: fx, a: angle) {
    _ = fire(TH16_RING_BALL2, BULLET_COLOR,
             $self_x - 4fx * v * cos(a), $self_y - 4fx * v * sin(a),
             v, a, none, none);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
